/** static void CreateHealthboxSprite(u8 battler) */
export function CreateHealthboxSprite(battler: any): any {
  if (battler < gBattlersCount)
      {
          let healthboxSpriteId: any = null;

          if (gBattleTypeFlags & ((1 << 7)) && battler == B_POSITION_PLAYER_LEFT)
              healthboxSpriteId = CreateSafariPlayerHealthboxSprites();
          else if (gBattleTypeFlags & ((1 << 9)) && battler == B_POSITION_PLAYER_LEFT)
              return;
          else
              healthboxSpriteId = CreateBattlerHealthboxSprites(battler);

          gHealthboxSpriteIds[battler] = healthboxSpriteId;
          InitBattlerHealthboxCoords(battler);
          SetHealthboxSpriteVisible(healthboxSpriteId);

          if (GetBattlerSide(battler) != (0))
              UpdateHealthboxAttribute(gHealthboxSpriteIds[battler],gEnemyParty[gBattlerPartyIndexes[battler]], HEALTHBOX_ALL);
          else if (gBattleTypeFlags & ((1 << 7)))
              UpdateHealthboxAttribute(gHealthboxSpriteIds[battler],gPlayerParty[gBattlerPartyIndexes[battler]], HEALTHBOX_SAFARI_ALL_TEXT);
          else
              UpdateHealthboxAttribute(gHealthboxSpriteIds[battler],gPlayerParty[gBattlerPartyIndexes[battler]], HEALTHBOX_ALL);

          if (GetBattlerPosition(battler) == B_POSITION_OPPONENT_RIGHT || GetBattlerPosition(battler) == B_POSITION_PLAYER_RIGHT)
              DummyBattleInterfaceFunc(gHealthboxSpriteIds[battler], TRUE);
          else
              DummyBattleInterfaceFunc(gHealthboxSpriteIds[battler], FALSE);

          if (GetBattlerSide(battler) != (0))
          {
              if (GetMonData(gEnemyParty[gBattlerPartyIndexes[battler]], MON_DATA_HP) == 0)
                  SetHealthboxSpriteInvisible(healthboxSpriteId);
          }
          else if (!(gBattleTypeFlags & ((1 << 7))))
          {
              if (GetMonData(gPlayerParty[gBattlerPartyIndexes[battler]], MON_DATA_HP) == 0)
                  SetHealthboxSpriteInvisible(healthboxSpriteId);
          }
      }
}

